<form class="settings-card-form popup-form" method="post" enctype="multipart/form-data" data-desktop-image="<?=sh($s['popup_desktop_image']??'')?>" data-mobile-image="<?=sh($s['popup_mobile_image']??'')?>" data-venue-phone="<?=sh($s['venue_phone']??'')?>"><div class="settings-heading"><div><h2>Website Popup</h2><p>Choose one responsive popup type.</p></div><label class="toggle"><input type="checkbox" name="popup_enabled" <?=($s['popup_enabled']??'0')==='1'?'checked':''?>><span>Enable Popup</span></label></div><input type="hidden" name="csrf" value="<?=sh($_SESSION['csrf'])?>"><div class="popup-type"><label><input type="radio" name="popup_type" value="text" <?=($s['popup_type']??'text')==='text'?'checked':''?>>Text Popup</label><label><input type="radio" name="popup_type" value="image" <?=($s['popup_type']??'text')==='image'?'checked':''?>>Image Popup</label></div><div data-popup-fields="text" class="form-grid"><label class="wide">Headline<input name="popup_headline" value="<?=sh($s['popup_headline']??'Special Offer for Event Bookings')?>"></label><label class="wide">Description<textarea name="popup_text" rows="4"><?=sh($s['popup_text']??'Book your wedding, engagement, or birthday event this month and get an exclusive offer.')?></textarea></label><label>Primary Button Text<input name="popup_primary_text" value="<?=sh($s['popup_primary_text']??'Enquire Now')?>"></label><label>Primary Button URL<input name="popup_primary_url" value="<?=sh($s['popup_primary_url']??'contact.html#enquire')?>"></label><label>Secondary Button Text<input name="popup_secondary_text" value="<?=sh($s['popup_secondary_text']??'WhatsApp Us')?>"></label><label>Secondary Button URL<input name="popup_secondary_url" value="<?=sh($s['popup_secondary_url']??'')?>"></label></div><div data-popup-fields="image" class="form-grid"><label>Desktop Image <small>1200×800, 3:2</small><input type="file" name="popup_desktop_image" accept="image/jpeg,image/png,image/webp"></label><label>Mobile Image <small>1080×1350, 4:5</small><input type="file" name="popup_mobile_image" accept="image/jpeg,image/png,image/webp"></label><label>What should happen when clicked?<select name="popup_click_type"><option value="none" <?=($s['popup_click_type']??'none')==='none'?'selected':''?>>No Action</option><option value="enquiry" <?=($s['popup_click_type']??'')==='enquiry'?'selected':''?>>Enquiry Page</option><option value="whatsapp" <?=($s['popup_click_type']??'')==='whatsapp'?'selected':''?>>WhatsApp</option><option value="custom" <?=($s['popup_click_type']??'')==='custom'?'selected':''?>>Custom web link</option></select></label><label>Custom URL<input name="popup_click_url" value="<?=sh($s['popup_click_url']??'')?>"></label></div><div class="form-grid"><label>Start Date<input type="date" name="popup_start_date" value="<?=sh($s['popup_start_date']??'')?>"></label><label>End Date<input type="date" name="popup_end_date" value="<?=sh($s['popup_end_date']??'')?>"></label><label>Show after visiting<select name="popup_delay_seconds"><option value="30" <?=((int)($s['popup_delay_seconds']??30))===30?'selected':''?>>30 seconds</option><option value="60" <?=((int)($s['popup_delay_seconds']??30))===60?'selected':''?>>60 seconds</option></select><small>Delay before the popup first appears on a visit.</small></label><label>Show again after (hours)<input type="number" name="popup_cooldown_hours" min="1" max="720" value="<?=sh($s['popup_cooldown_hours']??24)?>"></label></div><div class="preview-grid"><div><strong>Desktop Preview</strong><div class="popup-preview desktop" id="desktopPreview"></div></div><div><strong>Mobile Preview</strong><div class="popup-preview mobile" id="mobilePreview"></div></div></div><div class="button-row popup-form-actions"><button class="secondary-button" id="openPopupPreview" type="button">Open preview</button><button class="primary-button" name="action" value="save_popup">Save Changes</button></div></form>
